  f[at + 8] = b.strings.id(o.name);
  { const $v = o.from; f[at + 9] = $v.x; f[at + 10] = $v.y; f[at + 11] = $v.z; }
  { const $v = o.to; f[at + 12] = $v.x; f[at + 13] = $v.y; f[at + 14] = $v.z; }
